import Database from 'better-sqlite3';
import { drizzle, type BetterSQLite3Database } from 'drizzle-orm/better-sqlite3';
import { migrate } from 'drizzle-orm/better-sqlite3/migrator';
import { mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import * as schema from './schema';

export type OrbitDb = BetterSQLite3Database<typeof schema>;

/** Folder with Drizzle migrations (frontend/drizzle). Generated by `pnpm db:generate`. */
export const MIGRATIONS_DIR = resolve(process.cwd(), 'drizzle');

/** Open (creating if needed) the extension DB and apply pending migrations. */
export function openDb(path: string, migrationsFolder = MIGRATIONS_DIR): OrbitDb {
	if (path !== ':memory:') mkdirSync(dirname(resolve(path)), { recursive: true });
	const sqlite = new Database(path);
	sqlite.pragma('journal_mode = WAL');
	sqlite.pragma('foreign_keys = ON');
	const db = drizzle(sqlite, { schema });
	migrate(db, { migrationsFolder });
	return db;
}
